questionvariables.text:
/* Generate two random angles */
C: 20 + rand(40);  /* between 20 and 60 */
B: 30 + rand(50);  /* between 30 and 80 */
A: 180 - (B + C);  /* ensure valid triangle */

/* Given side */
a: 10;  /* opposite angle A */

/* Use sine rule: a/sin(A) = b/sin(B) = c/sin(C) */
b: a*sin(B*%pi/180)/sin(A*%pi/180);  /* opposite angle B */
c: a*sin(C*%pi/180)/sin(A*%pi/180);  /* opposite angle C */

/* Correct answer (let’s ask for side b) */
ta: decimalplaces(float(b),3);
